function dictDataHandler(json){let dictInfo=view.dictInfo;if(!dictInfo)return;if(json){let rows=json.rows;if(rows)Object.keys(rows).map(rowIndex=>{let row=rows[rowIndex].cells;if(row)Object.keys(row).map(colIndex=>{let cell=row[colIndex];if(cell.isDict===1){let tempText=cell.text;let tempDictList=dictInfo[cell.dictCode];if(tempDictList)cell.text=getDictTextByValue(tempDictList,tempText)}})})}}
function getDictTextByValue(ls,value){if(!ls||ls.length==0)return value;let text="";for(let item of ls)if(item.value==value){text=item.text;break}return text}
function getRepeatRange(rows){let sri,sci,eri,eci;let rowsIndex=Object.keys(rows);sri=rowsIndex[0];let beginCells=rows[sri].cells;let beginColArr=Object.keys(beginCells);sci=beginColArr[0];eri=rowsIndex[rowsIndex.length-1];let endCells=rows[eri].cells;let endColArr=Object.keys(endCells);eci=endColArr[endColArr.length-1];return{sri:Number(sri),sci:Number(sci),eri:Number(eri),eci:Number(eci)}}
function getQueryDefaultValue(defaultValue,type){if(defaultValue===0)if(type=="number")defaultValue=0;else defaultValue="0";else if(!defaultValue)defaultValue="";return defaultValue}function updateSearchForm(dbCode,name,value){let queryInfo=rpViewInst.queryInfo;let list=rpViewInst.configQueryList;if(list)for(let vo of list)if(vo.dbCode==dbCode&&vo.name==name)handleConfigToQueryInfo(vo,queryInfo,value);rpViewInst.queryInfo={...queryInfo}}
function handleConfigToQueryInfo(vo,queryInfo,defaultValue){let type=vo.type;let mode=vo.mode;let key=vo.key;if(mode==1){if(type=="date"||type=="time")if(defaultValue)queryInfo["onlyshow_"+key]=getDateByStr(defaultValue,vo.format);queryInfo[key]=defaultValue}else if(mode==2){let arr=(defaultValue+"").split("|");if(arr){if(arr.length>0)queryInfo[key+"_begin"]=arr[0].trim();if(arr.length>1)queryInfo[key+"_end"]=arr[1].trim();else queryInfo[key+"_end"]="";if(type=="date"||type=="time"){if(arr.length>
0&&arr[0])queryInfo["onlyshow_"+key+"_begin"]=getDateByStr(arr[0],vo.format);if(arr.length>1&&arr[1])queryInfo["onlyshow_"+key+"_end"]=getDateByStr(arr[1],vo.format)}}}else if(mode==3){let arr=(defaultValue+"").split(",");setTimeout(()=>{rpViewInst.setArrayValue("queryInfo","onlyshow_"+key,arr)},300);queryInfo[key]=defaultValue}else if(mode==4){queryInfo[key]=defaultValue;if(defaultValue){vo.select=false;vo.queryType=1}}else if(mode==5){if(defaultValue&&defaultValue.length>0)queryInfo[key]="*"+defaultValue+
"*";else queryInfo[key]="";queryInfo["onlyshow_"+key]=defaultValue}else{queryInfo[key]=defaultValue;if((type=="date"||type=="time")&&defaultValue)queryInfo["onlyshow_"+key]=getDateByStr(defaultValue,vo.format)}}function getSearchFormKey(vo){let key="";if(vo)if(vo.paramSearch==true)key=vo.name;else key=vo.dbCode+"__"+vo.name;return key}
function getFirstQueryInfo(list){let queryInfo={};if(list)for(let vo of list){vo["key"]=getSearchFormKey(vo);let defaultValue=getQueryDefaultValue(vo.defaultValue,vo.type);handleConfigToQueryInfo(vo,queryInfo,defaultValue)}return{list:list,queryInfo:queryInfo}}
function getDateByStr(str,format){if(!str)return"";str=str.trim();let date=new Date;if("HH:mm"==format){let hour=str.substring(0,2);date.setHours(hour);let mill=str.substring(3);date.setMinutes(mill)}else if("HH:mm:ss"==format){let hour=str.substring(0,2);date.setHours(hour);let mill=str.substring(3,5);date.setMinutes(mill);let sec=str.substring(6);date.setSeconds(sec)}else if("mm:ss"==format){let mill=str.substring(0,2);date.setMinutes(mill);let sec=str.substring(3);date.setSeconds(sec)}else if("HH"==
format)date.setHours(str);else if("mm"==format)date.setMinutes(str);else if("ss"==format)date.setSeconds(str);else return dayjs(str).toDate();return date}
